cc.Class({
    extends: cc.Component,

    properties: {
        _soundPath : "games/FantasyChocolateFactory/",
        _isPlayBgm:false,
    },

    /**
     * 播放音效
     * @param audioName
     */
    playEffect(audioName, isLoop) {
        return cc.vv.AudioManager.playEff(this._soundPath, audioName, true, isLoop);
    },

    /**
     * 停止音效
     * @param audioName
     */
    stopEffectByName(audioName) {
        cc.vv.AudioManager.stopEffectByName(audioName);
    },

    stopEffect() {
        cc.vv.AudioManager.stopAudio();
    },

    /**
     * 播放背景音乐 
     * 1.不传参数默认播放不循环的在cfg中配置的背景音乐
     * 2.传参数播放循环播放传入的背景音乐
     * @param {*} bgmName 
     */
    playBgm(bgmName) {
        if(bgmName) {
            Global.SlotsSoundMgr.playBgm(bgmName);
        }else {
            // Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
        }
    },

    /**
     * 免费游戏背景音乐
     */
    playFreeBgm() {
        this.playBgm("fgbgm");
    },
});
