/**
 * 弹窗管理器
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node
    },

    onLoad() {
        this.bg = this.node.getChildByName("bg");
    },

    showBg(boo) {
        this.bg.active = boo;
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     */
    async showWinFreeCoin(goldNumb) {
        SlotsFacade.soundMgr.playEffect("free_dialog_collect_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_coin");
        panel.active = true;
        panel.scale = 0;
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, Math.floor(goldNumb/1000));

        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        await new Promise(res=>{
            let okBtn = panel.getChildByName("btn_ok");
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("free_dialog_collect_click");
                okBtn.stopAllActions();
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示赢取免费次数
     * @param {number} cnt  
     * @param {*} cnt 
     * @param {*} isFirstTrigger 是否是首次触发
     */
    async showWinFreeCnt(cnt) {
        SlotsFacade.soundMgr.playEffect("frame_pickCollect");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_cnt");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent(cc.Label).string = cnt+"";

        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        await new Promise(res=>{
            cc.tween(panel)
                .delay(2)
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("frame_out");
                })
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.showBg(false);
                    panel.active = false;
                    SlotsFacade.soundMgr.playEffect("popup_out");
                    res();
                })
                .start();
        });
    },

    /**
     * 显示赢取jp奖励 
     * @param {*} jpType  jackport类型 1~4 mini~grand
     * @param {*} goldNumb 
     */
    async showWinJPCoin(jpType, goldNumb) {
        SlotsFacade.soundMgr.playEffect("popup_jp_window");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        let iconIndexCfg = {"1":0, "2":0, "3":1, "4":2};
        panel.getChildByName("jp_type_label").getComponent("ImgSwitchCmp").setIndex(iconIndexCfg[jpType+""]);
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);

        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        await new Promise(res=>{
            let okBtn = panel.getChildByName("btn_ok");
            let handler = ()=>{
                okBtn.stopAllActions();
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                SlotsFacade.soundMgr.playEffect("frame_out");
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 开始bonus game对话框
     */
    async showStartPick() {
        this.showBg(true);
        let panel = this.node.getChildByName("panel_bonus_start");
        panel.active = true;
        panel.scale = 0;
        
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        await new Promise(res=>{
            let okBtn = panel.getChildByName("btn_ok");
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("frame_out");
                okBtn.stopAllActions();
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        SlotsFacade.soundMgr.playEffect("popup_out");
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        })
    },
 })