let BubbleCfg = {
    width:160,
    height:160,
    speed:200, // 像素/每秒
    cdTime:1.8,  // 生成一行泡泡的cd时间
}; // 泡泡配置

cc.Class({
    extends: cc.Component,

    properties: {
        panel:cc.Node,
        free_cnt_count:cc.Node,
        pick_cnt_count:cc.Node,
        template_item_add_free:cc.Node,
        template_item_add_cnt:cc.Node,
        bubble_item:cc.Node,
        bubble_panel:cc.Node,
        cnt_ani_panel:cc.Node,

        _callBack:null, 
        _data:null,
        _bubbleItems:null,
        
    },

    start() {
        this.reset();
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onMsg, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onMsg, false, this);
    },

    sendMsg(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData._gameId;
        req.data = {rtype:1};
        cc.vv.NetManager.send(req);
    },

    onMsg(msg){
        if(msg.code == 200 && msg.data.rtype == 1){
            let freeInfo = msg.data.freeInfo;
            let deskInfo = SlotsFacade.dm.getDeskInfo();
            deskInfo.restFreeCount += freeInfo.freeCnt;
            deskInfo.allFreeCount += freeInfo.freeCnt;
            this.showResult(freeInfo.freeCnt);
        }
    },

    async showResult(cnt) {
        await SlotsFacade.popup.showWinFreeCnt(cnt);
        let deskInfo = SlotsFacade.dm.getDeskInfo();
        SlotsFacade.bottomCmp.ShowFreeModel(true, deskInfo.allFreeCount - deskInfo.restFreeCount, deskInfo.allFreeCount);
        this.exit();
    },

    reset() {
        this.bubble_panel.removeAllChildren(true);
        this.cnt_ani_panel.removeAllChildren(true);
        this._data = {
            freeCnt:0, // 获得的免费次数
            pickedCnt:0, // 已经pick的次数
            pickTotalCnt:0, // 可pick的总次数
            state:0, // 游戏状态 0-未开始 1-进行中 2-结束
            restCdTime:0, // 生成泡泡的剩余cd时间
            serverPickData:null, // 服务器pickData数据
        };
        this._bubbleItems = [];
        
        let pickData = SlotsFacade.dm.bonusData;
        if(pickData) {
            this._data.serverPickData = Global.copy(pickData);
            this._data.pickTotalCnt = this._data.serverPickData.initPick;
        }

        let freeCntLabel = this.free_cnt_count.getChildByName("label").getComponent(cc.Label);
        freeCntLabel.string = this._data.freeCnt;
        let pickCntLabel = this.pick_cnt_count.getChildByName("label").getComponent(cc.Label);
        pickCntLabel.string = `PICK  ${this._data.pickedCnt}  OF  ${this._data.pickTotalCnt}`;
    },

    /**
     * 更新免费次数
     * @param {*} cnt 
     */
    _addFreeCnt(cnt) {
        this._data.freeCnt += cnt;
        let label = this.free_cnt_count.getChildByName("label").getComponent(cc.Label);
        label.string = this._data.freeCnt + "";
        
        let spine = this.free_cnt_count.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.clearTracks();
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
    },

    /**
     * 更新pick次数
     * @param {*} cnt
     */
    _addPickCnt(cnt) {
        this._data.pickTotalCnt += cnt;
        let label = this.pick_cnt_count.getChildByName("label").getComponent(cc.Label);
        label.string = `PICK  ${this._data.pickedCnt}  OF  ${this._data.pickTotalCnt}`;
        let spine = this.pick_cnt_count.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.clearTracks();
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
    },

    async enter(callBack, isReconect) {
        this._callBack = callBack;
        this.reset();
        // 转场动画
        if(!isReconect) {
            SlotsFacade.mainPanel.showSceneTransition();
            await SlotsFacade.delayTime(2);
        }
        SlotsFacade.soundMgr.playBgm("ngbgm");
        this.panel.active = true;
        this.panel.opacity = 0xff;
        await SlotsFacade.popup.showStartPick();
        this._data.state = 1;
    },

    /**
     * 生成一行泡泡
     */
    generateBubble() {
        this._data.restCdTime = BubbleCfg.cdTime;
        let len = 4;
        let panelWidth = this.bubble_panel.width;
        let height = BubbleCfg.height*2; // 包围盒高
        let width = this.bubble_panel.width / len; // 包围盒宽
        let diffW = width - BubbleCfg.width; // 冗余宽度
        let diffH = height - BubbleCfg.height; // 冗余高度
        for(let i=0; i<len; i++) {
            let item = cc.instantiate(this.bubble_item);
            item.active = true;
            item.isAlive = true;
            item.parent = this.bubble_panel;
            item.x = -panelWidth/2 + i*width + BubbleCfg.width/2 + Math.random()*diffW;
            item.y = -height + BubbleCfg.height/2 + Math.random()*diffH;
            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation0" + [1, 2][Math.floor(Math.random()*2)], true);
            item.on(cc.Node.EventType.TOUCH_START, this.touchBubbleHandler.bind(this), this);
            this._bubbleItems.push(item);
        }
    },

    touchBubbleHandler(evt) {
        if(this._data.state != 1) {
            return;
        }
        if(this._data.serverPickData.finalResult.length < 1) {
            return;
        }
        let item =evt.target;
        if(!item.isAlive) {
            return;
        }
        item.isAlive = false;
        SlotsFacade.soundMgr.playEffect("bubble_click");
        this._data.pickedCnt++;
        let label = this.pick_cnt_count.getChildByName("label").getComponent(cc.Label);
        label.string = `PICK  ${this._data.pickedCnt}  OF  ${this._data.pickTotalCnt}`;

        for(let i=0; i<this._bubbleItems.length; i++) {
            if(item == this._bubbleItems[i]) {
                this._bubbleItems.splice(i, 1);
                break;
            }
        }

        let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation03", false);
        spine.setCompleteListener(()=>{
            spine.node.removeFromParent(true);
        })

        let vo = this._data.serverPickData.finalResult.shift();
        let startPos = cc.v2(item.x, item.y);
        let endP = [this.free_cnt_count, this.pick_cnt_count][vo.type-1].convertToWorldSpaceAR(cc.v2(0, 0));
        endP = this.cnt_ani_panel.convertToNodeSpaceAR(endP);
        this.processReward(vo, startPos, endP);
    },

    processReward(vo, startP, endP) {
        let node = cc.instantiate([this.template_item_add_free, this.template_item_add_cnt][vo.type-1]);
        node.getChildByName("label").getComponent(cc.Label).string = "+" + vo.cnt;
        node.active = true;
        node.parent = this.cnt_ani_panel;
        node.x = startP.x;
        node.y = startP.y;
        
        cc.tween(node)
            .to(0.5, {x:endP.x, y:endP.y})
            .call(()=>{
                node.removeFromParent();
                if(vo.type == 1) {
                    this._addFreeCnt(vo.cnt);
                }else {
                    this._addPickCnt(vo.cnt);
                }
                node.removeFromParent(true);
                if(this._data.serverPickData.finalResult.length < 1) {
                    this.pickComplete();    
                }
                
            })
            .start();
    },

    async pickComplete() {
        if(this._data.state == 2) {
            return;    
        }
        this._data.state = 2;
        this.clearBubble();
        await SlotsFacade.delayTime(1);
        this.sendMsg();
    },

    destroyABubble(item) {
        if(!item) {
            return;
        }
        if(item.parent) {
            item.off(cc.Node.EventType.TOUCH_START, this.touchBubbleHandler.bind(this), this);
            item.removeFromParent(true);
        }
    },

    clearBubble() {
        this._bubbleItems.forEach(element => {
            this.destroyABubble(element);
        });
    },

    exit() {
        cc.tween(this.panel)
            .to(0.5, {opacity:0})
            .call(()=>{
                this.panel.active = false;
                if(this._callBack) {
                    this._callBack();
                }
            })
            .start();
    },

    update(dt) {
        if(!this._data || this._data.state != 1) {
            return;
        }
        this._data.restCdTime -= dt;
        if(this._data.restCdTime <= 0) {
            this.generateBubble();
        }

        let dis = BubbleCfg.speed * dt; // 移动距离
        for(let i=0; i<this._bubbleItems.length; i++) {
            let item = this._bubbleItems[i];
            if(item.y > this.bubble_panel.height + BubbleCfg.height) {
                // 超框删除
                this._bubbleItems.splice(i, 1);
                item.removeFromParent(true);
                i--;
            }else {
                item.y += dis;
            }
        }
        
    }
})