let BubbleCfg = {
    "1":{spine:"bubbleNormal", stopAni:"animation03", appearAni:"animation06", moveAni:["animation01", "animation02"], candyMagicAni:"animation3"}, // 普通泡泡
    "2":{spine:"bubbleNormal", stopAni:"animation09", appearAni:"animation10", moveAni:["animation07", "animation08"], candyMagicAni:"animation1", hasCandySpread:true}, // 普通4格泡泡
    "3":{spine:"bubbleMinor", stopAni:"animation03", appearAni:"animation06", moveAni:["animation01", "animation02"], winAni:"animation11", candyMagicAni:"animation3"}, // minor泡泡
    "4":{spine:"bubbleMinor", stopAni:"animation09", appearAni:"animation10", moveAni:["animation07", "animation08"], winAni:"animation12", candyMagicAni:"animation1", hasCandySpread:true}, // minor4格泡泡
    "5":{spine:"bubbleMajor", stopAni:"animation03", appearAni:"animation06", moveAni:["animation01", "animation02"], winAni:"animation11", candyMagicAni:"animation3"}, // major泡泡
    "6":{spine:"bubbleMajor", stopAni:"animation09", appearAni:"animation10", moveAni:["animation07", "animation08"], winAni:"animation12", candyMagicAni:"animation1", hasCandySpread:true}, // major4格泡泡
    "7":{spine:"bubbleGrand", stopAni:"animation03", appearAni:"animation06", moveAni:["animation01", "animation02"], winAni:"animation11", candyMagicAni:"animation3"}, // grand泡泡
    "8":{spine:"bubbleGrand", stopAni:"animation09", appearAni:"animation10", moveAni:["animation07", "animation08"], winAni:"animation12", candyMagicAni:"animation1", hasCandySpread:true}, // grand4格泡泡
};

cc.Class({
    extends: cc.Component,

    properties: {
        bubble_machine_node:cc.Node,
        spine_machine:sp.Skeleton,
        spine_machine_buble:sp.Skeleton,
        spine_big_bubble_effect:sp.Skeleton,
        bubble_node:cc.Node,    // 泡泡节点

        bubbleNormal:cc.Node,
        bubbleMinor:cc.Node,
        bubbleMajor:cc.Node,
        bubbleGrand:cc.Node,
        candy_magic:cc.Node,

        _isOpen:false,
        _bubbleItems:[],
        _bubbleStartPos:null,
    },

    onLoad() {
        this._bubbleItems = [];
        let pos = cc.v2(this.spine_machine_buble.node.x, this.spine_machine_buble.node.y);
        pos = this.bubble_machine_node.convertToWorldSpaceAR(pos);
        this._bubbleStartPos = this.bubble_node.convertToNodeSpaceAR(pos);
    },

    start() {
        this._initListener();
        this.showBubbleMachine(true);
        this.resetBubble();
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showBubbleMachine();
            this.resetBubble(true);
        },this);

        this.bubble_machine_node.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(!this._isOpen) {
                this._openBubble();
            }
        }, this);
    },

    /**
     * 打开气泡机
     */
    _openBubble() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 显示气泡机
     * @param {*} isInit 是否是初始化
     */
    showBubbleMachine(isInit) {
        let boo = SlotsFacade.dm.canBubble();
        if(isInit) {
            if(boo) {
                this.spine_machine_buble.node.active = true;
                this.spine_machine.setAnimation(0, "animation1", true);    
            }else {
                this.spine_machine_buble.node.active = false;
                this.spine_machine.setAnimation(0, "animation3", false);    
            }
        }else {
            if(boo) {
                if(!this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("bubbleMachine_open");
                    this.spine_machine.setAnimation(0, "animation4", false);
                    this.spine_machine.setCompleteListener(()=>{
                        this.spine_machine.setCompleteListener(null);
                        this.spine_machine.setAnimation(0, "animation1", true);
                        this.spine_machine_buble.node.active = true;
                    })
                }
            }else {
                this.spine_machine_buble.node.active = false;
                if(this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("bubbleMachine_close");
                    this.spine_machine.setAnimation(0, "animation2", false);
                }
            }
        }
        this._isOpen = boo;
    },

    /**
     * 获取一个气泡的位置
     * @param {*} bubbleInfoVo 
     */
    getABubblePos(bubbleInfoVo) {
        let currIndexs = bubbleInfoVo.currIdxs;
        let posArr = [];
        for(let i=0; i<currIndexs.length; i++) {
            let pos = SlotsFacade.slots.getIdxGlobalPos(currIndexs[i]);
            pos = this.bubbleNormal.convertToNodeSpaceAR(pos);
            posArr.push(pos);
        }
        if(posArr.length == 1) {
            return posArr[0];
        }else if(posArr.length == 2) {
            if(currIndexs[0] <= 5) {
                return cc.v2((posArr[0].x+posArr[1].x)/2, posArr[0].y+SlotsFacade.dm.getGameCfg().symbolSize.height/2);
            }else {
                return cc.v2((posArr[0].x+posArr[1].x)/2, posArr[0].y-SlotsFacade.dm.getGameCfg().symbolSize.height/2);
            }
        }else if(posArr.length == 4) {
            return cc.v2((posArr[0].x+posArr[3].x)/2, (posArr[0].y+posArr[3].y)/2);
        }else {
            console.log("Error#getABubblePos#", bubbleInfoVo);
        }
    },

    /**
     * 创建一个泡泡
     * @param {*} bubbleInfoVo 
     */
    createABubble(bubbleInfoVo, parent) {
        let cfgVo = BubbleCfg[bubbleInfoVo.type + ""];
        let item = cc.instantiate(this[cfgVo.spine]);
        item.active = true;
        item.info = {id:bubbleInfoVo.id, type:bubbleInfoVo.type};
        if(parent) {
            item.parent = parent;
            item.getComponent(sp.Skeleton).setAnimation(0, cfgVo.stopAni, false);
        }
        return item;
    },

    /**
     * 清除泡泡
     */
    clearBubble() {
        this._bubbleItems.forEach(element => {
            element.removeFromParent(true);
        });
        this._bubbleItems = [];
    },

    /**
     * 直接初始化泡泡
     */
    resetBubble() {
        this.clearBubble();
        let bubbleInfo = SlotsFacade.dm.getCurrBubbleInfo();
        if(!bubbleInfo) {
            return;
        }
        for(let i=0; i<bubbleInfo.length; i++) {
            let vo = bubbleInfo[i];
            let bubble = this.createABubble(vo, this.bubble_node);
            let pos = this.getABubblePos(vo);
            bubble.x = pos.x;
            bubble.y = pos.y;
            this._bubbleItems.push(bubble);
        }
    },

    /**
     * 是否已经有泡泡
     */
    bubbleItemsIncludeId(id) {
        for(let i=0; i<this._bubbleItems.length; i++) {
            if(this._bubbleItems[i].info.id == id) {
                return true;
            }
        }
        return false;
    },

    /**
     * 打开泡泡机时添加泡泡
     */
    async addBubbleOnOpenBubbleMachine(bubbleInfo) {
        let height = SlotsFacade.dm.getGameCfg().symbolSize.height;
        let newBubbleCnt = 0;
        for(let i=0; i<bubbleInfo.length; i++) {
            let vo = bubbleInfo[i];
            if(vo.prevIdxs && vo.prevIdxs.length > 0) {
                continue;
            }
            if(this.bubbleItemsIncludeId(vo.id)) {
                continue;
            }
            newBubbleCnt++;
            // 播放大泡泡背景效果
            if([2,4,6,8].includes(vo.type)) {
                this.spine_big_bubble_effect.node.active = true;
                this.spine_big_bubble_effect.setAnimation(0, "animation", false);
                this.spine_big_bubble_effect.setCompleteListener(()=>{
                    this.spine_big_bubble_effect.setCompleteListener(null);
                    this.spine_big_bubble_effect.node.active = false;
                });
            }
            // 生成新气泡
            let bubble = this.createABubble(vo);
            bubble.active = true;
            bubble.x = this._bubbleStartPos.x;
            bubble.y = this._bubbleStartPos.y;
            bubble.parent = this.bubble_node;
            let endPos = this.getABubblePos(vo);
            endPos.y -= height;

            let cfgVo = BubbleCfg[vo.type+""];
            let spine = bubble.getComponent(sp.Skeleton);
            spine.setAnimation(0, cfgVo.appearAni, false);

            // 移动气泡
            cc.tween(bubble)
                .delay(0.5)
                .to(1.5, {x:endPos.x, y:endPos.y}, {easing:"cubicIn"})
                .start();
            
            // 添加到泡泡数组
            this._bubbleItems.push(bubble);
        }
        if(newBubbleCnt) {
            SlotsFacade.soundMgr.playEffect("bubble_create" + (newBubbleCnt>3?3:newBubbleCnt));
            await SlotsFacade.delayTime(2.2);
        }
    },

    /**
     * 关闭泡泡机时添加泡泡
     */
    async addBubbleOnCloseBubbleMachine(bubbleInfo) {
        let height = SlotsFacade.dm.getGameCfg().symbolSize.height;
        let newBubbleCnt = 0;
        for(let i=0; i<bubbleInfo.length; i++) {
            let vo = bubbleInfo[i];
            if(vo.prevIdxs && vo.prevIdxs.length > 0) {
                continue;
            }
            if(this.bubbleItemsIncludeId(vo.id)) {
                continue;
            }
            newBubbleCnt++;
            // 生成新气泡
            let endPos = this.getABubblePos(vo);
            endPos.y -= height;
            let bubble = this.createABubble(vo);
            bubble.active = true;
            bubble.x = endPos.x;
            bubble.y = endPos.y;
            bubble.parent = this.bubble_node;

            let cfgVo = BubbleCfg[vo.type+""];
            let spine = bubble.getComponent(sp.Skeleton);
            spine.setAnimation(0, cfgVo.stopAni, false);
            
            // 添加到泡泡数组
            this._bubbleItems.push(bubble);
        }
    },

    /**
     * 添加刚生成的气泡
     */
    async addBubble() {
        let bubbleInfo = SlotsFacade.dm.getCurrBubbleInfo();
        if(!bubbleInfo || bubbleInfo.length < 1) {
            return;
        }
        if(SlotsFacade.dm.canBubble()) {
            await this.addBubbleOnOpenBubbleMachine(bubbleInfo);
        }else {
            await this.addBubbleOnCloseBubbleMachine(bubbleInfo);
        }
    },

    /**
     * 移动泡泡
     */
    moveBubble() {
        let bubbleInfo = SlotsFacade.dm.getCurrBubbleInfo();
        let bi = Array.isArray(bubbleInfo) ? bubbleInfo : (bubbleInfo && typeof(bubbleInfo) === 'object') ? Object.values(bubbleInfo) : []
        let bubbleInfoMap = {};
        /*bubbleInfo*/bi.forEach(element => { // By JerryWong
            bubbleInfoMap[element.id] = element;
        });
        let height = SlotsFacade.dm.getGameCfg().symbolSize.height;
        for(let i=0; i<this._bubbleItems.length; i++) {
            let item = this._bubbleItems[i];
            let vo = bubbleInfoMap[item.info.id];
            let cfgVo = BubbleCfg[item.info.type+""];
            let spine = item.getComponent(sp.Skeleton);
            spine.setAnimation(0, cfgVo.moveAni[Math.floor(Math.random()*cfgVo.moveAni.length)], true);
            if(vo) {
                // 移动泡泡
                let pos = this.getABubblePos(vo);
                cc.tween(item)
                    .to(1.2, {x:pos.x, y:pos.y})
                    .call(()=>{
                        spine.setAnimation(0, cfgVo.stopAni, false);
                    })
                    .start();
            }else {
                // 移除泡泡
                this._bubbleItems.splice(i, 1);
                i--;
                cc.tween(item)
                    .to(0.8, {y:item.y+height*1.5})
                    .to(0.5, {opacity:0})
                    .call(()=>{
                        item.removeFromParent(true);
                    })
                    .start();
            }
        }
    },

    /**
     * 显示泡泡结束位置
     */
    showBubbleEndPos() {
        let bubbleInfo = SlotsFacade.dm.getCurrBubbleInfo();
        if(!bubbleInfo) {
            return;
        }
        let bi = Array.isArray(bubbleInfo) ? bubbleInfo : (bubbleInfo && typeof(bubbleInfo) === 'object') ? Object.values(bubbleInfo) : []
        let bubbleInfoMap = {};
        /*bubbleInfo*/bi.forEach(element => { // By JerryWong
            bubbleInfoMap[element.id] = element;
        });
        for(let i=0; i<this._bubbleItems.length; i++) {
            let item = this._bubbleItems[i];
            let vo = bubbleInfoMap[item.info.id];
            //let cfgVo = BubbleCfg[item.info.type+""];
            if(vo) {
                let pos = this.getABubblePos(vo);
                item.x = pos.x;
                item.y = pos.y;
            }
        }
    },

    getBubbleItemById(id) {
        for(let i=0; i<this._bubbleItems.length; i++) {
            let item = this._bubbleItems[i];
            if(item.info.id == id) {
                return item;
            }
        }
        return null;
    },

    /**
     * 显示jackport奖励
     * @param {*} effectVo 
     */
    async showJackPort(effectVo) {
        SlotsFacade.soundMgr.playEffect("bubble_jp_animation");
        let item = this.getBubbleItemById(effectVo.id);
        let cfgVo = BubbleCfg[item.info.type + ""];
        let spine = item.getComponent(sp.Skeleton);
        spine.setAnimation(0, cfgVo.winAni, false);
        await new Promise(res=>{
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                res();
            });
        });
        await SlotsFacade.popup.showWinJPCoin(effectVo.jackpotId, effectVo.jackpotValue);
    },

    /**
     * 显示candyMagic动画
     * @param {*} effectVo 
     */
    async showCandyMagic(effectVo) {
        SlotsFacade.soundMgr.playEffect("bubble_transform");
        let item = this.getBubbleItemById(effectVo.id);
        item.active = false;
        let cfgVo = BubbleCfg[item.info.type + ""];
        // 创建candymagic 动画
        let candyMagicItem = cc.instantiate(this.candy_magic);
        candyMagicItem.active = true;
        candyMagicItem.x = item.x;
        candyMagicItem.y = item.y;
        candyMagicItem.parent = this.bubble_node;

        // 显示candy magic 背景光圈
        let candySpread = candyMagicItem.getChildByName("spine_spread");
        if(cfgVo.hasCandySpread) {
            candySpread.active = true;
            candySpread.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        }

        // 显示candy magic动画
        let spine = candyMagicItem.getChildByName("spine_candy").getComponent(sp.Skeleton);
        spine.setAnimation(0, cfgVo.candyMagicAni, false);
        await new Promise(res=>{
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                candyMagicItem.removeFromParent(true);
                item.active = true;
                item.getComponent(sp.Skeleton).setAnimation(0, cfgVo.stopAni, false);
                res();
            });
        });

        // 分裂气球
        let currIdxs = effectVo.currIdxs;
        let wildIdxs = effectVo.wildIdxs;
        let bubbleArr = [];
        for(let i=0; i<wildIdxs.length; i++) {
            let idx = wildIdxs[i];
            if(currIdxs.includes(idx)) {
                continue;
            }
            let bubble = this.createABubble({id:0, type:1}, this.bubble_node);
            bubble.x = item.x;
            bubble.y = item.y;
            bubbleArr.push(bubble);
            let endPos = this.getABubblePos({currIdxs:[idx]});
            cc.tween(bubble)
                .to(0.5, {x:endPos.x, y:endPos.y})
                .start();
        }
        await SlotsFacade.delayTime(0.6);
        bubbleArr.forEach(element => {
            element.removeFromParent(true);
        });
    },

    /**
     * 显示分列效果
     */
    async showBubbleEffect() {
        let bubbleEffect = SlotsFacade.dm.getSpinData().bubbleEffects;
        if(!bubbleEffect || bubbleEffect.length < 1) {
            return;
        }
        // 显示jackpot
        for(let i=0; i<bubbleEffect.length; i++) {
            let vo = bubbleEffect[i];
            if(vo.jackpotId) {
                await this.showJackPort(vo);
            }
        }
        // 显示candy magic 并且分裂气球
        let promiseArr = [];
        for(let i=0; i<bubbleEffect.length; i++) {
            let vo = bubbleEffect[i];
            if(vo.isDivide > 0) {
                promiseArr.push(this.showCandyMagic(vo));
            }
        }
        if(promiseArr.length) {
            await Promise.all(promiseArr);
        }

        // 变wild
        let hasDivide = false;
        this.showBubbleNode(false);
        let wildIdxs = [];
        for(let i=0; i<bubbleEffect.length; i++) {
            let vo = bubbleEffect[i];
            wildIdxs = wildIdxs.concat(vo.currIdxs);
            wildIdxs = wildIdxs.concat(vo.wildIdxs);
            if(!hasDivide && vo.isDivide) {
                hasDivide = true;
            }
        }
        let setWildIdxs = [];
        wildIdxs.forEach(element => {
            if(!setWildIdxs.includes(element)) {
                setWildIdxs.push(element);
            }
        });
        let symbolArr = SlotsFacade.slots.getSymbolsByServerIds(setWildIdxs);
        for(let i=0; i<symbolArr.length; i++) {
            let symbol = symbolArr[i];
            symbol.changeToWild();
        }
        SlotsFacade.soundMgr.playEffect("bubble_wild");

        if(hasDivide) {
            await SlotsFacade.delayTime(0.3);
            let nTotalBet = cc.vv.gameData.GetTotalBet();
            let nMul = SlotsFacade.dm.GetGameWin() / nTotalBet;
            if(nMul >= 10) {
                SlotsFacade.soundMgr.playEffect("fg_bell");
                let shakeTime = 1;
                let shakeOffset = 5;
                Global.shakeNode(SlotsFacade.mainPanel.bg, shakeOffset, shakeTime);
                Global.shakeNode(SlotsFacade.mainPanel.jpNode, shakeOffset, shakeTime);
                Global.shakeNode(SlotsFacade.mainPanel.slots, shakeOffset, shakeTime);
                await SlotsFacade.delayTime(shakeTime + 0.2);
            }
        }
    },

    showBubbleNode(boo) {
        this.bubble_node.active = boo;
        if(boo && this._bubbleItems) {
            for(let item of this._bubbleItems) {
                if(!item.info) {
                    continue;
                }
                let cfgVo = BubbleCfg[item.info.type.toString()];
                item.getComponent(sp.Skeleton).setAnimation(0, cfgVo.stopAni, false);
            }
        }
    }
})